mapper.select:

SELECT id, symbol, source, verified_through, content_hash, raw_json, fetched_at, last_verified_at
FROM market_factor_snapshot
WHERE symbol=#{symbol}
  AND source=#{source}
  AND verified_through>=#{end}
  AND (source='BAOSTOCK' OR STR_TO_DATE(JSON_UNQUOTE(JSON_EXTRACT(raw_json, '$.coverageFrom')), '%Y-%m-%d') <=#{start})
ORDER BY verified_through DESC, id DESC
LIMIT 1
